[metadata] {"type": "create", "filePath": "/workspace/repo/packages/expo-observe/src/integrations/expo-router/router.ts", "content": "type RouteInfo = {
  pathname: string;
};

type Navigation = {
  isFocused(): boolean;
};

export type OptionalRouter = {
  useRoute: () => unknown;
  useNavigation: () => Navigation;
  useCurrentRouteInfo: () => RouteInfo;
};

/**
 * Detects whether `expo-router` is running in the host app. The router registers
 * itself on `globalThis.expo.router` at startup, so its presence is a reliable
 * signal that router-aware integrations can safely resolve the router hooks.
 */
function detectRouterInstalled(): boolean {
  return !!(
    typeof globalThis !== 'undefined' &&
    (globalThis as any).expo &&
    'router' in (globalThis as any).expo
  );
}

export const isRouterInstalled = detectRouterInstalled();

/**
 * The subset of `expo-router` hooks used by the interactivity integration, or
 * `undefined` when the router is not installed. `useCurrentRouteInfo` is composed
 * from `usePathname` so callers get a stable `{ pathname }` shape.
 */
export const optionalRouter: OptionalRouter | undefined = (() => {
  if (!isRouterInstalled) {
    return undefined;
  }

  try {
    // Resolved lazily so apps without `expo-router` never attempt to load it.
    const expoRouter = require('expo-router');
    return {
      useRoute: expoRouter.useRoute,
      useNavigation: expoRouter.useNavigation,
      useCurrentRouteInfo: () => ({ pathname: expoRouter.usePathname() }),
    };
  } catch {
    return undefined;
  }
})();
