[metadata] {"type": "create", "filePath": "/workspace/repo/packages/expo-observe/src/integrations/expo-router/init.ts", "content": "import { optionalRouter } from './router';

let initialized = false;

/**
 * Whether {@link initRouterIntegration} has already run. Used to keep the
 * integration idempotent across repeated `configure` calls.
 */
export function isInitialized(): boolean {
  return initialized;
}

/**
 * Subscribes to router navigation lifecycle events and returns a cleanup
 * function that removes the subscriptions.
 */
export function initListeners(): () => void {
  // The router hooks drive interactivity marking at render time, so there are
  // no imperative listeners to attach here. The cleanup handle is kept so the
  // integration surface can grow without changing callers.
  return () => {};
}

/**
 * Wires up the router integration exactly once. Subsequent calls are no-ops.
 */
export function initRouterIntegration(): void {
  if (initialized || !optionalRouter) {
    return;
  }

  initialized = true;
