import { optionalRouter } from './router';

/**
 * Router-aware companion to {@link useObserve}. When `expo-router` is installed
 * it returns a `markInteractive` variant that automatically tags each metric
 * with the current route's `pathname` and skips marking while the screen is not
 * focused. Returns `null` when the router is unavailable so callers can fall
 * back to the plain `AppMetrics.markInteractive`.
 */
export function useObserveForRouter(): ((options?: Record<string, unknown>) => void) | null {
  if (!optionalRouter) {
    return null;
  }

  optionalRouter.useRoute();
  const navigation = optionalRouter.useNavigation();
  const routeInfo = optionalRouter.useCurrentRouteInfo();

  return (options?: Record<string, unknown>) => {
    if (!navigation.isFocused()) {
      return;
    }

    AppMetrics.markInteractive({ ...options, routeName: routeInfo.pathname });
  };
}
